+## 2026-10-11 03:20 — Frontend: Flow Detect/Lostのペアガイド
+
+### Scope
+
+- frontend
+- Flow Detected／Recovered→Lostへペアの接続線、両端マーカー、時間ツールチップ、画面外ガイドを拡張する。
+
+### Completed
+
+- `eventRelations.ts`へ関連判定、ペア型、端点定義、共通ツールチップを分離し、Flowの開始／終了を扱うようにした。
+- `EventLog.tsx`と`EventRelationGuide.tsx`で同じstart／endモデルと端点定義を使用し、開始を青系の丸印、Lostを警告色の四角印で表示するようにした。
+- 同一flowの最も近いライフサイクル境界だけを候補とし、再検出・再開・重複Lostを飛び越して別区間と接続しないようにした。
+- 履歴は既存APIのtypes条件でFlowライフサイクル3種を同時取得し、100件の検索上限に達した結果はペア生成に使用しないようにした。取得した境界を選択中保持し、後から到着した境界でも古いペアを解除する。
+- 時間ツールチップに、Lost判定遅延を含み得るイベント間隔であることを追記した。
+- `events-relations.test.cjs`へ純粋関数の単体テストを追加し、`events-guide.test.cjs`へFlowの画面内／画面外・Range外・境界・上限のブラウザ回帰確認を追加した。
+
+### Decisions
+
+- 詳細はdesign-notes.mdの「EventsのFlow活動区間ペア表示」を参照。
+- Alertや各種Occur／Recoverの端点表記・チェック記号を維持し、Lostを正常復帰として描かない。
+
+### Verification
+
<truncated omitted_approx_tokens="1598" />on findRelatedEvent(events: EventLogItem[], source: EventLogItem, relation: EventRelation) {
+  if (relation.boundaryTypes && !source.flowKey) return null;
+  // For a flow, the next lifecycle transition must be its counterpart. Do not
+  // skip an intervening Detect/Recovered/Lost just because it is not a match.
+  const types = relation.boundaryTypes ?? relation.counterpartTypes;
+  const nearest = events.reduce<EventLogItem | null>((closest, candidate) => {
+    if (candidate.id === source.id || !types.includes(candidate.type) || !sameRelationTarget(source, candidate)) return closest;
+    if (relation.direction === "before" ? candidate.time >= source.time : candidate.time <= source.time) return closest;
+    if (!closest || Math.abs(candidate.time - source.time) < Math.abs(closest.time - source.time)) return candidate;
+    // Conflicting simultaneous transitions are ambiguous; prefer the blocker.
+    if (candidate.time === closest.time && !relation.counterpartTypes.includes(candidate.type)) return candidate;
+    return closest;
+  }, null);
+  return nearest && relation.counterpartTypes.includes(nearest.type) ? nearest : null;
+}
+
+function alertStateKey(event: EventLogItem) {
+  const detail = event.detail;
+  if (!detail || typeof detail !== "object" || Array.isArray(detail)) return null;
+  const key = (detail as Record<string, unknown>).state_key;
+  return typeof key === "string" && key ? key : null;
+}
+
+function sameRelationTarget(source: EventLogItem, candidate: EventLogItem) {
+  const sourceStateKey = alertStateKey(source);
+  const candidateStateKey = alertStateKey(candidate);
+  if (sourceStateKey || candidateStateKey) return Boolean(sourceStateKey && sourceStateKey === candidateStateKey);
+  if (source.flowKey || candidate.flowKey) return Boolean(source.flowKey && source.flowKey === candidate.flowKey);
+  return Boolean(source.streamKey && source.streamKey === candidate.streamKey);
+}
"}

